  'guide.inclusion.title': 'Jalankan program inklusif dan adaptif',
  'guide.inclusion.why': 'Biarkan atlet penyandang disabilitas dan para-atlet bergabung dan berkembang di program Anda tanpa mengungkapkan diagnosis: atur apa yang ditawarkan program, pastikan setiap sesi adaptif siap, dan biarkan atlet membagikan hanya kebutuhan operasional yang mereka pilih.',
  'guide.inclusion.s1': 'Buka Akademi, lalu Inklusi, lalu Pengaturan program, pilih program dan tentukan siapa yang boleh bergabung, templat adaptasi olahraga, penyesuaian yang ditawarkan, fitur venue, dan rasio pendamping yang dibutuhkan.',
  'guide.inclusion.s2': 'Minta pengelola venue mencatat fitur aksesibilitas tiap venue (lift, jalur tanpa tangga, ruang ganti aksesibel, hoist kolam) agar sesi dapat diperiksa terhadapnya.',
  'guide.inclusion.s3': 'Atlet, atau wali terverifikasi dari atlet muda, membuka Akademi saya, lalu Akomodasi, dan membagikan hanya yang dibutuhkan staf, kepada siapa, dan sampai kapan. Mereka dapat menariknya kapan saja.',
  'guide.inclusion.s4': 'Buka Inklusi, lalu Kesiapan sesi, pilih sesi dan selesaikan setiap kekurangan: venue, pendamping, jadwal jaga, dan kredensial pelatih utama. Pelatih dan staf venue hanya melihat apa yang dibagikan kepada mereka, dan setiap akses dicatat untuk atlet.',
  'guide.inclusion.s5': 'Catat asesmen adaptif yang dipimpin pelatih dengan tingkat deskriptif, bukan skor tunggal, dan minta penilai kedua menyetujuinya. Direktur hanya melihat jumlah di Ringkasan.',

